function el(tag,cls='',content){const e=document.createElement(tag);if(cls)e.className=cls;if(content!==undefined)e.textContent=txt(content);return e;}
function svg(tag,attrs={},content){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,String(v)));if(content!==undefined)e.textContent=txt(content);return e;}
