function tooltip(event,value){const node=$('tooltip');node.textContent=value;node.hidden=false;node.style.left=Math.max(8,Math.min(event.clientX+14,innerWidth-Math.min(360,innerWidth-20)-10))+'px';node.style.top=Math.max(8,Math.min(event.clientY+12,innerHeight-node.offsetHeight-12))+'px';}
