function downloadable(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(name,rows){if(!rows.length){message('내보낼 행이 없습니다.','amber');return;}const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];const quote=v=>{let out=txt(v??'');if(typeof v==='string'&&/^\s*[=+\-@\t\r]/.test(out))out="'"+out;return'"'+out.replaceAll('"','""')+'"';};downloadable(name,'\ufeff'+[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function table(root,rows,columns){root.replaceChildren();const t=el('table'),head=el('thead'),tr=el('tr'),body=el('tbody');columns.forEach(([key,title])=>tr.append(el('th','',title||key)));head.append(tr);for(const row of rows){const r=el('tr');for(const [key] of columns)cell(r,['status','severity','review_status'].includes(key)?status(row[key]):typeof row[key]==='object'?txt(row[key]):row[key]);body.append(r);}if(!rows.length)empty(body,columns.length,'표시할 자료가 없습니다.');t.append(head,body);root.append(t);}
function pagination(root,total,page,onPage,size=40){root.replaceChildren();const pages=Math.max(1,Math.ceil(total/size));const prev=el('button','','이전'),next=el('button','','다음');prev.disabled=page<=0;next.disabled=page>=pages-1;prev.onclick=()=>onPage(page-1);next.onclick=()=>onPage(page+1);root.append(prev,el('span','',`${page+1} / ${pages} · ${total}행`),next);}
