function renderAxisContext(){const root=$('axis-context'),axes=arr(S.bundle.axis_by_cohort),snapshot=S.options.summary==='snapshot';root.replaceChildren();root.hidden=!S.bundle.axis_label&&!snapshot;if(S.bundle.axis_label)root.append(el('p','',S.bundle.axis_label));if(axes.length){const detail=el('details');detail.append(el('summary','','비교군별 관측 축 확인'));for(const axis of axes)detail.append(el('p','',`${axis.cohort}: ${axis.axis_label} · ${axis.is_lifetime?'수명 축':'수명 축으로 해석하지 않음'}`));root.append(detail);}if(snapshot)root.append(el('p','','단일 시점의 유효 값 1개 이상을 사용합니다. 시작과 끝은 같으며 구간 중앙값을 계산하지 않습니다.'));$('life-max').disabled=snapshot;$('min-points').disabled=snapshot;$('min-points').min=snapshot?'1':'2';}
function changeSummary(previous){if(S.options.summary==='snapshot'){if(previous!=='snapshot')S.rangeBeforeSnapshot={life_min:S.options.life_min,life_max:S.options.life_max,min_points:S.options.min_points,windows:clone(S.options.windows)};S.options.life_max=S.options.life_min;S.options.min_points=1;S.options.windows=arr(S.options.windows).map(window=>({...window,life_max:window.life_min}));message('단일 시점으로 변경했습니다. 각 관측 창은 해당 시작 시점 한 곳만 사용합니다.');}else if(previous==='snapshot'){const old=S.rangeBeforeSnapshot;S.options.min_points=Math.max(2,old?.min_points||3);if(old&&old.life_max>old.life_min){S.options.life_min=old.life_min;S.options.life_max=old.life_max;S.options.windows=clone(old.windows);}else{if(!(S.options.life_max>S.options.life_min))S.options.life_max=Number(S.options.life_min)+S.options.min_points-1;S.options.windows=arr(S.options.windows).map(window=>window.life_max>window.life_min?window:{...window,life_max:Number(window.life_min)+S.options.min_points-1});}message('구간 대표값으로 변경했습니다. 실제 관측된 시작·끝과 최소 관측 수를 확인한 뒤 계산하세요.');}renderOptionControls();}

function normalizeOptions(options={}){const comparison=S.bundle.comparison||{};const defaults={enabled_modules:MODULES.map(x=>x[0]),metric_ids:arr(S.bundle.metrics).filter(m=>m.selected_by_default!==false).map(metricId),design_field_ids:arr(S.bundle.design_fields).map(metricId),life_min:comparison.life_min??1,life_max:comparison.life_max??100,summary:comparison.summary||'median',min_points:comparison.min_points??3,min_overlap:comparison.min_overlap??3,min_coverage:comparison.min_overlap_fraction??.6,scale_mode:'current',cross_filter:{design_min:0,design_max:1,electrochem_min:0,electrochem_max:1},controlled:{target:'',controls:[],tolerances:{}},windows:[],replicate_group_by:['design_id','batch_id']};return{...defaults,...clone(options),cross_filter:{...defaults.cross_filter,...options.cross_filter},controlled:{...defaults.controlled,...options.controlled,tolerances:{...(options.controlled?.tolerances||{})}}};}
function graphs(){return S.analysis.graphs||{};}
function graph(){return graphs()[S.mode]||{nodes:[],edges:[],metrics:[],cohorts:[]};}
function allNodes(){const found=new Map();for(const g of Object.values(graphs()))for(const n of arr(g?.nodes))if(!found.has(experimentId(n)))found.set(experimentId(n),n);return[...found.values()];}
function nodeById(id,g=graph()){return arr(g.nodes).find(n=>experimentId(n)===id);}
