function switchMode(mode){if(S.mode===mode)return;S.mode=mode;S.positions.clear();S.edge=null;const n=nodeById(S.selected);S.cohort=n?.cohort||arr(graph().cohorts)[0]?.cohort||'';if(!n)S.selected=arr(graph().nodes)[0]?experimentId(graph().nodes[0]):'';if(!nodeById(S.compare))S.compare='';S.edge=arr(graph().edges).find(e=>(e.source===S.selected&&e.target===S.compare)||(e.target===S.selected&&e.source===S.compare))||null;renderNetwork();renderInspector();renderFeatures();renderEdge();}
function selectExperiment(id){S.selected=id;if(S.compare===id)S.compare='';S.edge=null;renderNetwork();renderInspector();renderFeatures();renderEdge();renderCrossview();renderTrajectory();renderEvidenceSelectors();}
function choosePair(source,target,navigate=true){const current=nodeById(source);if(!current){const alternative=S.mode==='design'?'electrochem':'design';if(nodeById(source,graphs()[alternative]||{}))S.mode=alternative;}S.selected=source;S.compare=target;S.cohort=nodeById(source)?.cohort||S.cohort;S.edge=arr(graph().edges).find(e=>(e.source===source&&e.target===target)||(e.source===target&&e.target===source))||null;renderNetwork();renderInspector();renderFeatures();renderEdge();if(navigate){if(!S.visible.includes('network'))S.visible.push('network');renderModules();showPanel('network');}hideTooltip();}
function designPriority(m){return ['cathode_active_material','anode_active_material'].includes(metricId(m))?0:m.kind==='composition'?1:m.kind==='numeric'?2:3;}
function renderInspector(){const a=nodeById(S.selected),b=nodeById(S.compare);$('selected-title').textContent=a?label(a):'실험을 선택하세요';$('selected-coverage').textContent=a?`${arr(a.features).filter(f=>hasValue(f.value)).length}개 항목`:'';const metadata=$('selected-metadata');metadata.replaceChildren();if(a)for(const [name,value]of[['셀',a.cell_id],['시험',a.test_id],['프로토콜',a.protocol],['화학계',a.chemistry],['온도',finite(a.temperature_c)?num(a.temperature_c)+' °C':a.temperature_c],['비교군',a.cohort]]){const n=el('div');n.append(el('dt','',name),el('dd','',value));metadata.append(n);}const linked=arr(S.bundle.experiments).find(row=>experimentId(row)===S.selected)?.knowledge_link;if(linked){for(const[name,value]of[['장표 실험',linked.experiment_name],['샘플 ID',linked.sample_id],['시험 날짜 · 세트',[linked.test_date,linked.set_no].filter(Boolean).join(' · ')],['장표 근거',arr(linked.evidence_ids).length+'개 · 아래 근거 위치에서 확인'],['등록 버전',linked.record_id+' / '+linked.revision],['비교 미반영 항목',arr(linked.unapplied_metadata_fields).join(', ')]]){if(!value)continue;const n=el('div');n.append(el('dt','',name),el('dd','',value));metadata.append(n);}}if(linked){const detail=el('details'),summary=el('summary','','근거 위치 · '+arr(linked.evidence_ids).length+'개 펼치기');detail.append(summary);const groups=new Map();for(const item of arr(linked.evidence_locations)){if(!groups.has(item.document_id))groups.set(item.document_id,[]);groups.get(item.document_id).push(item);}let index=0;for(const[documentId,items]of groups){const title=el('p','', '문서 '+(++index));title.title=documentId;detail.append(title);for(const item of items){const entry=el('div','',item.locator);entry.title=item.evidence_id;detail.append(entry);}}metadata.append(detail);}const linkWarnings=arr(S.bundle.knowledge_summary?.issues).filter(item=>item.experiment_id===S.selected);if(linkWarnings.length){const names={knowledge_link_stale_source:'원본이 변경되어 연결 재검토 필요',knowledge_link_stale_record:'장표 등록 정보가 변경되어 연결 재검토 필요',knowledge_link_existing_metadata_conflict:'기존 등록 정보와 충돌',knowledge_composition_basis_unverified:'조성 기준이 불명확하거나 달라 해당 비율을 비교에서 보류'};const n=el('div');n.append(el('dt','','장표 연결 검토'),el('dd','',linkWarnings.map(item=>names[item.reason]||'연결 근거 재검토 필요').join(' · ')));metadata.append(n);}const compare=$('compare-experiment');compare.replaceChildren(option('','비교 실험 선택'));for(const n of arr(graph().nodes).filter(n=>a&&n.cohort===a.cohort&&experimentId(n)!==S.selected))compare.append(option(experimentId(n),label(n)));compare.value=S.compare;const legendRoot=$('comparison-legend');legendRoot.replaceChildren();if(a)legend(legendRoot,'A · '+label(a),COLORS[0]);if(b)legend(legendRoot,'B · '+label(b),COLORS[2]);$('radar-svg').toggleAttribute('hidden',S.mode==='design');$('radar-note').hidden=S.mode==='design';$('design-compare').hidden=S.mode!=='design';if(S.mode==='design'){const body=$('design-compare-body');body.replaceChildren();for(const m of arr(graph().metrics).slice().sort((a,b)=>designPriority(a)-designPriority(b))){const row=el('tr'),name=cell(row,m.label||metricId(m));name.append(el('small','',[m.unit,m.kind==='composition'?basis(m.composition_basis):''].filter(Boolean).join(' · ')));cell(row,valueLabel(feature(a,metricId(m))?.value,m.kind==='composition'?m.unit:''));cell(row,valueLabel(feature(b,metricId(m))?.value,m.kind==='composition'?m.unit:''));body.append(row);}if(!arr(graph().metrics).length)empty(body,3,'계산된 설계 항목이 없습니다.');}else renderRadar();}
function renderRadar(){const root=$('radar-svg');root.replaceChildren();const metrics=arr(graph().metrics).slice(0,8),a=nodeById(S.selected),b=nodeById(S.compare);if(metrics.length<3||!a){root.append(svg('text',{x:180,y:145,'text-anchor':'middle',fill:'#8299a5','font-size':11},'레이더에는 유효한 지표 축 3개 이상이 필요합니다.'));return;}const point=(i,ratio)=>{const angle=-Math.PI/2+i*2*Math.PI/metrics.length;return{x:180+Math.cos(angle)*92*ratio,y:140+Math.sin(angle)*92*ratio};};for(const r of [.25,.5,.75,1])root.append(svg('polygon',{points:metrics.map((_,i)=>{const p=point(i,r);return`${p.x},${p.y}`;}).join(' '),fill:'none',stroke:r===.5?'#afcad0':'#e0eaee','stroke-dasharray':r===.5?'3 3':'none'}));metrics.forEach((m,i)=>{const p=point(i,1),l=point(i,1.27);root.append(svg('line',{x1:180,y1:140,x2:p.x,y2:p.y,stroke:'#e5edef'}),svg('text',{x:l.x,y:l.y+3,'text-anchor':'middle','font-size':8,fill:'#7a929e'},short(m.label||metricId(m),18)));});for(const [n,color]of[[a,COLORS[0]],[b,COLORS[2]]])if(n){const points=metrics.map((m,i)=>{const v=feature(n,metricId(m));return finite(v?.scaled)?point(i,(Math.max(-2,Math.min(2,v.scaled))+2)/4):null;});if(points.every(Boolean))root.append(svg('polygon',{points:points.map(p=>`${p.x},${p.y}`).join(' '),fill:color,'fill-opacity':.08,stroke:color,'stroke-width':1.7}));else points.forEach((p,i)=>{const q=points[(i+1)%points.length];if(p&&q)root.append(svg('line',{x1:p.x,y1:p.y,x2:q.x,y2:q.y,stroke:color,'stroke-width':1.7}));});points.forEach((p,i)=>{if(!p)return;const dot=svg('circle',{cx:p.x,cy:p.y,r:3,fill:color});dot.append(svg('title',{},`${label(n)} / ${metrics[i].label}\n${num(feature(n,metricId(metrics[i]))?.value)} ${metrics[i].unit||''}`));root.append(dot);});}}
function renderFeatures(){const root=$('feature-body');root.replaceChildren();const query=$('feature-search').value.toLowerCase().trim(),features=arr(nodeById(S.selected)?.features).filter(f=>!query||[metricId(f),f.label].join(' ').toLowerCase().includes(query));for(const f of features){const m=graphMetric(metricId(f)),row=el('tr'),name=cell(row,f.label||metricId(f),'metric-name');name.append(el('small','',metricId(f)));cell(row,valueLabel(f.value,m.kind==='composition'?m.unit:''));cell(row,[f.unit,m.kind==='composition'?basis(m.composition_basis):''].filter(Boolean).join(' · ')||'—');cell(row,f.valid_count??'—','numeric');cell(row,S.mode==='design'?'—':`${num(f.first_life)}–${num(f.last_life)}`,'numeric');cell(row,'').append(tag(f.status||'missing'));root.append(row);}if(!features.length)empty(root,6,'선택한 실험의 항목이 없습니다.');}
function renderEdge(){$('edge-detail').hidden=!S.edge;if(!S.edge)return;const edge=S.edge,design=S.mode==='design';$('edge-title').textContent=`${label(nodeById(edge.source))} ↔ ${label(nodeById(edge.target))}`;$('edge-description').textContent=`유사도 ${num(edge.similarity,3)} · 공통 ${edge.shared_metrics??edge.shared_fields??'—'}개 · 관측 범위 ${pct(edge.coverage)}`;$('edge-distance-heading').textContent=design?'가중 거리 기여':'표준화 거리';const root=$('edge-body');root.replaceChildren();for(const c of arr(edge.contributors)){const m=graphMetric(c.metric_id),row=el('tr'),name=cell(row,c.label||c.metric_id,'metric-name');name.append(el('small','',m.unit||''));cell(row,valueLabel(c.left,m.kind==='composition'?m.unit:''));cell(row,valueLabel(c.right,m.kind==='composition'?m.unit:''));cell(row,num(c.raw_delta),'numeric');const value=design?c.weighted_distance:c.standardized_distance,dist=cell(row,num(value,3),'numeric');if(design)dist.append(el('small','',`항목 거리 ${num(c.standardized_distance,3)} · 가중치 ${num(c.weight)}`));root.append(row);}if(!arr(edge.contributors).length)empty(root,5,'기여 항목 정보가 없습니다.');}
function chart(root,series,{xLabel='',yLabel='',xDomain,yDomain,xTicks,emptyText='표시할 유효 관측값이 없습니다.',width=1000,height=430}={}){root.replaceChildren();root.setAttribute('viewBox',`0 0 ${width} ${height}`);const pad={left:78,right:30,top:25,bottom:65},points=series.flatMap(s=>s.points).filter(p=>finite(p.x)&&finite(p.y));if(!points.length){root.append(svg('text',{x:width/2,y:height/2,'text-anchor':'middle',fill:'#8ba0aa','font-size':13},emptyText));return null;}let [xmin,xmax]=xDomain||[Math.min(...points.map(p=>p.x)),Math.max(...points.map(p=>p.x))], [ymin,ymax]=yDomain||[Math.min(...points.map(p=>p.y)),Math.max(...points.map(p=>p.y))];if(xmin===xmax){xmin-=.5;xmax+=.5;}if(ymin===ymax){const pad=Math.max(Math.abs(ymin)*.05,.1);ymin-=pad;ymax+=pad;}if(!yDomain){const pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;}const x=v=>pad.left+(v-xmin)/(xmax-xmin)*(width-pad.left-pad.right),y=v=>height-pad.bottom-(v-ymin)/(ymax-ymin)*(height-pad.top-pad.bottom);for(let i=0;i<=5;i++){const value=ymin+(ymax-ymin)*i/5,py=y(value);root.append(svg('line',{x1:pad.left,y1:py,x2:width-pad.right,y2:py,class:'chart-grid'}),svg('text',{x:pad.left-10,y:py+4,'text-anchor':'end',class:'axis-tick'},num(value,3)));}const xt=xTicks||Array.from({length:6},(_,i)=>({value:xmin+(xmax-xmin)*i/5,label:num(xmin+(xmax-xmin)*i/5,2)}));for(const tick of xt)root.append(svg('text',{x:x(tick.value),y:height-pad.bottom+22,'text-anchor':'middle',class:'axis-tick'},short(tick.label,24)));root.append(svg('text',{x:width/2,y:height-14,'text-anchor':'middle',class:'axis-label'},xLabel),svg('text',{x:20,y:height/2,transform:`rotate(-90 20 ${height/2})`,'text-anchor':'middle',class:'axis-label'},yLabel));series.forEach((s,index)=>{const color=s.color||COLORS[index%COLORS.length];let path='';let started=false;for(const p of s.points){if(!finite(p.x)||!finite(p.y)){started=false;continue;}path+=(started?' L':' M')+x(p.x)+' '+y(p.y);started=true;}if(!s.dotsOnly)root.append(svg('path',{d:path,fill:'none',stroke:color,'stroke-width':s.width||1.8,opacity:.9}));const sampled=s.points.length>180?s.points.filter((_,i)=>i%Math.ceil(s.points.length/180)===0):s.points;for(const p of sampled){if(!finite(p.x)||!finite(p.y))continue;const dot=svg('circle',{cx:x(p.x),cy:y(p.y),r:s.dotsOnly?4.5:2.1,fill:color,opacity:s.dotsOnly?.78:.6,class:'chart-dot'});dot.onmousemove=e=>tooltip(e,`${s.label||''}\n${p.tooltip||`${xLabel}: ${num(p.x)}\n${yLabel}: ${num(p.y)}`}`);dot.onmouseleave=hideTooltip;if(p.onClick)dot.onclick=p.onClick;root.append(dot);}});return{x,y,pad,xmin,xmax,ymin,ymax,width,height};}

function renderCrossview(){const pairs=arr(S.analysis.cross_pairs).filter(p=>!$('cross-selected-only').checked||p.source===S.selected||p.target===S.selected),valid=pairs.filter(p=>finite(p.design_similarity)&&finite(p.electrochem_similarity));$('cross-count').textContent=`${valid.length}개 유효 쌍 / ${pairs.length}개`;const root=$('cross-svg'),series=[{label:'실험 쌍',color:COLORS[0],dotsOnly:true,points:valid.map(p=>({x:p.design_similarity,y:p.electrochem_similarity,tooltip:`${label(anyNode(p.source))} ↔ ${label(anyNode(p.target))}\n설계 ${num(p.design_similarity,3)} · 전기화학 ${num(p.electrochem_similarity,3)}\n관측 ${pct(p.design_coverage)} / ${pct(p.electrochem_coverage)}`,onClick:()=>choosePair(p.source,p.target)}))}];const plot=chart(root,series,{xLabel:'설계 유사도',yLabel:'전기화학 유사도',xDomain:[0,1],yDomain:[0,1],width:900,height:480,emptyText:'두 기준의 값이 모두 있는 실험 쌍이 없습니다.'});if(plot){for(const v of [S.applied.cross_filter?.design_min,S.applied.cross_filter?.design_max])if(finite(v)&&v>0&&v<1)root.append(svg('line',{x1:plot.x(v),y1:plot.y(0),x2:plot.x(v),y2:plot.y(1),stroke:'#b8cbd0','stroke-dasharray':'5 4'}));for(const v of[S.applied.cross_filter?.electrochem_min,S.applied.cross_filter?.electrochem_max])if(finite(v)&&v>0&&v<1)root.append(svg('line',{x1:plot.x(0),y1:plot.y(v),x2:plot.x(1),y2:plot.y(v),stroke:'#b8cbd0','stroke-dasharray':'5 4'}));}S.crossPage=Math.min(S.crossPage,Math.max(0,Math.ceil(pairs.length/40)-1));const body=$('cross-body');body.replaceChildren();for(const p of pairs.slice(S.crossPage*40,(S.crossPage+1)*40)){const row=el('tr');cell(row,label(anyNode(p.source)),'metric-name');cell(row,label(anyNode(p.target)),'metric-name');cell(row,num(p.design_similarity,3),'numeric');cell(row,num(p.electrochem_similarity,3),'numeric');cell(row,`${pct(p.design_coverage)} / ${pct(p.electrochem_coverage)}`,'numeric');const button=el('button','button','두 실험 보기');button.onclick=()=>choosePair(p.source,p.target);cell(row,'').append(button);body.append(row);}if(!pairs.length)empty(body,6,'조건에 맞는 실험 쌍이 없습니다.');pagination($('cross-pagination'),pairs.length,S.crossPage,page=>{S.crossPage=page;renderCrossview();});}
function reconcileDesignControls(){const allowed=new Set([...arr(S.options.design_field_ids),...arr(S.bundle.control_fields).map(metricId)]);if(!S.options.design_field_ids.includes(S.options.controlled.target))S.options.controlled.target='';S.options.controlled.controls=arr(S.options.controlled.controls).filter(id=>allowed.has(id));}
function renderControlledControls(){const fields=arr(S.bundle.design_fields).filter(f=>arr(S.options.design_field_ids).includes(metricId(f))),select=$('controlled-target');select.replaceChildren(option('','목표 조건을 선택하세요'));for(const f of fields)select.append(option(metricId(f),f.label||metricId(f)));select.value=S.options.controlled.target||'';const root=$('controlled-controls');root.replaceChildren();const controlFields=[...new Map([...fields,...arr(S.bundle.control_fields)].map(f=>[metricId(f),f])).values()];for(const f of controlFields){const id=metricId(f);if(id===S.options.controlled.target)continue;const box=el('div','control-field'),row=el('label'),check=el('input');check.type='checkbox';check.checked=arr(S.options.controlled.controls).includes(id);check.onchange=()=>{S.options.controlled.controls=check.checked?[...S.options.controlled.controls,id]:S.options.controlled.controls.filter(x=>x!==id);if(!check.checked)delete S.options.controlled.tolerances[id];renderControlledControls();dirty();};row.append(check,document.createTextNode(f.label||id));box.append(row);if(f.kind==='numeric'||f.kind==='composition'){const tolerance=el('label','tolerance','허용 차이 '),input=el('input');input.type='number';input.min='0';input.step='any';input.value=S.options.controlled.tolerances[id]??0;input.disabled=!check.checked;input.oninput=()=>{S.options.controlled.tolerances[id]=input.value===''?null:Number(input.value);dirty();};tolerance.append(input,document.createTextNode(f.kind==='composition'?'wt%p · 절대차 합/2':f.unit||''));box.append(tolerance);}else box.append(el('p','help','등록된 분류명 정확 일치'));root.append(box);}if(!fields.length)root.append(el('p','help','실제 계산에 사용할 설계 항목을 먼저 선택하세요.'));}
function renderControlled(){const filter=$('controlled-status').value,rows=arr(S.analysis.controlled_pairs).filter(p=>!filter||p.status===filter),body=$('controlled-body');body.replaceChildren();S.controlledPage=Math.min(S.controlledPage,Math.max(0,Math.ceil(rows.length/40)-1));$('controlled-count').textContent=`${rows.length}개 후보 쌍`;const labels=ids=>arr(ids).map(id=>getMetric(id,true).label||id).join(', ')||'—';for(const p of rows.slice(S.controlledPage*40,(S.controlledPage+1)*40)){const row=el('tr'),name=cell(row,'','metric-name'),button=el('button','text-button',`${label(anyNode(p.source))} ↔ ${label(anyNode(p.target))}`);button.onclick=()=>choosePair(p.source,p.target);name.append(button);cell(row,'').append(tag(p.status));cell(row,labels(p.changed));cell(row,labels(p.confounders));cell(row,labels(p.missing));const detail=el('details','detail-values');detail.append(el('summary','','값과 함께 바뀐 성분'));for(const[id,d]of Object.entries(p.delta||{})){const spec=getMetric(id,true),line=el('p','',`${spec.label||id}: ${valueLabel(d.left,d.kind==='composition'?d.unit:'')} → ${valueLabel(d.right,d.kind==='composition'?d.unit:'')} ${d.unit||''}`);if(finite(d.delta))line.append(el('small','',`차이 ${num(d.delta)} ${d.unit||''}`));if(d.coupled)line.append(el('small','',`합계 제약으로 성분이 함께 변함 · ${valueLabel(d.component_deltas,'wt%p')}`));detail.append(line);}cell(row,'').append(detail);body.append(row);}if(!rows.length)empty(body,6,'계산된 통제 비교 쌍이 없습니다. 목표 조건과 통제 조건을 선택해 계산하세요.');pagination($('controlled-pagination'),rows.length,S.controlledPage,page=>{S.controlledPage=page;renderControlled();});}
function renderEvidenceSelectors(){const root=$('evidence-experiment'),selected=root.value;root.replaceChildren();for(const node of allNodes())root.append(option(experimentId(node),label(node)));root.value=allNodes().some(n=>experimentId(n)===selected)?selected:S.selected;const supported=S.server;$('evidence-load').disabled=!supported;$('evidence-status').textContent=S.evidence.length?'표시된 곡선은 아래 원본·레코드 근거에서 불러왔습니다.':supported?'실험과 cycle을 선택하여 실제 저장된 측정 근거를 불러오세요.':'곡선 원본 조회에는 로컬 서버가 필요합니다. 이 파일에서는 저장된 요약 결과를 볼 수 있습니다.';}
async function loadEvidence(){const id=$('evidence-experiment').value;if(!id)throw new Error('근거를 확인할 실험을 선택하세요.');const cycle=$('evidence-cycle').value,ids=[id];if($('evidence-compare').checked&&S.compare&&S.compare!==id)ids.push(S.compare);const request=++S.evidenceRequest;$('evidence-status').textContent='원본 측정 근거를 읽고 있습니다…';const result=await Promise.all(ids.map(experiment=>api('/api/evidence?'+new URLSearchParams({experiment_id:experiment,...(cycle?{cycle}:{})}))));if(request!==S.evidenceRequest)return;S.evidence=result;const choices=$('evidence-cycle');choices.replaceChildren(option('','자동 선택'));for(const item of arr(result[0].cycles))choices.append(option(item.cycle,result[0].axis_kind==='rpt_internal_cycle'?`RPT 내부 cycle ${item.cycle} · 수명 cycle 아님`:`cycle ${item.cycle} · life ${item.life_index??'—'}`));choices.value=String(result[0].selected_cycle??cycle??'');renderEvidence();}
function renderEvidence(){const list=S.evidence,root=$('evidence-svg'),nativeView=list.length>0&&list.every(e=>e.native_view===true);document.querySelectorAll('.evidence-chart').forEach(b=>b.classList.toggle('active',b.dataset.chart===S.evidenceChart));const legendRoot=$('evidence-legend');legendRoot.replaceChildren();const curves=list.flatMap((e,index)=>arr(e.curves).map(c=>({...c,experiment_id:e.experiment_id,color:COLORS[index*2],sourceData:e}))),series=[];for(const c of curves){let points=[],xLabel,yLabel;if(S.evidenceChart==='vq'){points=arr(c.points).map(p=>({x:nativeView?p.capacity_native:p.capacity_ah,y:nativeView?p.voltage_native:p.voltage_v,tooltip:nativeView?`Q ${num(p.capacity_native)} · V ${num(p.voltage_native)} (CYC 원본 단위 미확정)`: `Q ${num(p.capacity_ah)} Ah · V ${num(p.voltage_v)} V\n원본 레코드 ${p.source_row??'—'}`}));}else if(S.evidenceChart==='vt'){points=arr(c.points).map(p=>({x:p.time_s,y:nativeView?p.voltage_native:p.voltage_v,tooltip:nativeView?`시간 ${num(p.time_s)} s · 전압 ${num(p.voltage_native)} (CYC 원본 단위 미확정)`: `시간 ${num(p.time_s)} s · 전압 ${num(p.voltage_v)} V\n원본 레코드 ${p.source_row??'—'}`}));}else if(S.evidenceChart==='dqdv'){points=arr(c.dqdv).map(p=>({x:p.voltage_v,y:p.value}));}else if(S.evidenceChart==='dvdq'){points=arr(c.dvdq).map(p=>({x:p.capacity_ah,y:p.value}));}const seriesLabel=`${label(anyNode(c.experiment_id))} · ${c.leg||'구간'} ${c.segment_id??''}`;if(points.length)series.push({label:seriesLabel,color:c.color,points});legend(legendRoot,seriesLabel,c.color);}const labels={vq:['용량 (Ah)','전압 (V)'],vt:['시간 (s)','전압 (V)'],dqdv:['전압 (V)','dQ/dV (Ah/V)'],dvdq:['용량 (Ah)','dV/dQ (V/Ah)']};if(nativeView){labels.vq=['용량 (CYC 원본 단위 미확정)','전압 (CYC 원본 단위 미확정)'];labels.vt=['시간 (s · 구간별)','전압 (CYC 원본 단위 미확정)'];}if(S.evidenceChart==='pulse'){root.replaceChildren();root.setAttribute('viewBox','0 0 1000 640');const top=svg('svg',{x:0,y:0,width:1000,height:320}),bottom=svg('svg',{x:0,y:320,width:1000,height:320});root.append(top,bottom);for(const [chartRoot,key,name]of[[top,'voltage_v','전압 (V)'],[bottom,'current_a','전류 (A)']])chart(chartRoot,curves.map(c=>({label:label(anyNode(c.experiment_id))+' · '+(c.leg||''),color:c.color,points:arr(c.points).map(p=>({x:p.time_s,y:p[key],tooltip:`시간 ${num(p.time_s)} s · ${name} ${num(p[key])}\n원본 레코드 ${p.source_row??'—'}`}))})),{xLabel:'시간 (s)',yLabel:name,height:320,emptyText:'측정 시계열을 불러오세요.'});}else chart(root,series,{xLabel:labels[S.evidenceChart][0],yLabel:labels[S.evidenceChart][1],emptyText:'이 구간의 유효 곡선이 없습니다. 미분 미산출 사유와 품질 기록을 확인하세요.'});const downsampled=curves.filter(c=>c.sampling?.downsampled||c.derivative?.downsampled),warnings=list.flatMap(e=>arr(e.warnings));$('evidence-sampling').textContent=downsampled.length?`${downsampled.length}개 구간은 표시용 대표점 · 원본 보존`:'저장된 관측점 표시';$('evidence-status').textContent=list.length?`${list.length}개 실험 · ${curves.length}개 구간. source_row는 CSV 물리 줄이 아닌 1부터 시작하는 데이터 레코드 번호입니다.${warnings.length?' '+warnings.map(w=>status(w.reason)+(w.fields?.length?' ('+w.fields.join(', ')+')':'')).join(' · '):''}`:S.server?'근거 불러오기를 실행하세요.':'원본 곡선 조회는 로컬 서버가 필요합니다.';const provenance=$('evidence-provenance');provenance.replaceChildren();for(const e of list){const box=el('div');box.append(el('strong','',label(anyNode(e.experiment_id))));const lines=[`실행: ${e.run_path||'—'}`,`원본 SHA256: ${e.source_hash||'—'}`,`선택 cycle: ${e.selected_cycle??'—'}`];for(const c of arr(e.curves)){lines.push(`${c.leg||'구간'} ${c.segment_id??''}: ${c.source?.path||'—'}`);lines.push(`원본 레코드 ${c.source?.row_start??'—'}–${c.source?.row_end??'—'} · ${c.source?.row_basis||'data record'}`);if(c.source?.member)lines.push(`원본 조각: ${c.source.member} · 물리 줄 ${c.source.member_row_start??'—'} → ${c.source.last_member||c.source.member} · 물리 줄 ${c.source.member_row_end??'—'}`);if(c.sampling)lines.push(`대표점 ${c.sampling.returned_points??'—'}/${c.sampling.original_points??'—'} · ${c.sampling.method||'—'}`);if(c.derivative)lines.push(`미분: ${c.derivative.status||'—'} · ${c.derivative.reason||c.derivative.method||''}`);}box.append(el('pre','',lines.join('\n')));provenance.append(box);}const flatten=key=>list.flatMap(e=>arr(e[key]).map(r=>({experiment_id:e.experiment_id,...r})));const pulses=flatten('pulses'),quality=flatten('quality'),diagnostics=flatten('diagnostics');table($('pulse-table'),pulses,[['experiment_id','실험'],['cycle','cycle'],['pulse_time_s','pulse 시간'],['delta_voltage_v','ΔV (V)'],['delta_current_a','ΔI (A)'],['baseline_voltage_v','기준 전압 (V)'],['response_voltage_v','응답 전압 (V)'],['resistance_mohm','저항 mΩ'],['baseline_source_row','기준 레코드'],['response_source_row_left','응답 왼쪽'],['response_source_row_right','응답 오른쪽']].filter(([k])=>k==='experiment_id'||pulses.some(r=>k in r)));table($('quality-table'),quality,[['experiment_id','실험'],['code','코드'],['severity','수준'],['detail','내용'],['source_row','원본 레코드']]);table($('diagnostics-table'),diagnostics,[['experiment_id','실험'],['status','판정'],['severity','수준'],['metric','지표'],['value','값'],['unit','단위'],['reasons','이유'],['candidate_causes','후보 원인'],['review_status','검토 상태'],['evidence','근거']]);}
function renderWindowEditor(){const root=$('window-editor');root.replaceChildren();arr(S.options.windows).forEach((w,index)=>{const row=el('div','window-row');for(const[key,title,type]of[['label','구간 이름','text'],['life_min','시작','number'],['life_max','끝','number']]){const l=el('label','',title),input=el('input');input.type=type;if(type==='number')input.step='any';input.value=w[key]??'';if(key==='life_max'&&S.options.summary==='snapshot')input.disabled=true;input.oninput=()=>{S.options.windows[index][key]=type==='number'?(input.value===''?null:Number(input.value)):input.value;if(key==='life_min'&&S.options.summary==='snapshot'){S.options.windows[index].life_max=S.options.windows[index].life_min;row.querySelectorAll('input')[2].value=S.options.windows[index].life_max??'';}dirty();};l.append(input);row.append(l);}const remove=el('button','icon-button','×');remove.setAttribute('aria-label','구간 삭제');remove.onclick=()=>{S.options.windows.splice(index,1);renderWindowEditor();dirty();};row.append(remove);root.append(row);});if(!arr(S.options.windows).length)root.append(el('p','help','‘구간 추가’로 비교할 공통 관측 구간을 만드세요.'));}
