function replicateKey(record){return record.group_id||stable(record.group||{});}
function replicateGroups(){const groups=new Map();for(const row of arr(S.analysis.replicates))if(!groups.has(replicateKey(row)))groups.set(replicateKey(row),row);return[...groups.values()];}
function selectedReplicateRows(){return arr(S.analysis.replicates).filter(row=>replicateKey(row)===S.replicateGroupId);}
