async function refreshState(manual=false){if(S.busy)return;if(location.protocol!=='http:'&&location.protocol!=='https:'){if(manual)message('이 파일은 저장된 결과입니다. 최신 결과를 보려면 로컬 서버 주소로 열거나 새로 생성한 index.html을 다시 여세요.','amber');return;}try{const result=await api('/api/state');if(result.unchanged){const reconnecting=!S.server;S.server=true;$('refresh-error').hidden=!S.lastServerError;$('refresh-error').textContent=S.lastServerError?'새 자료 갱신에 실패하여 이전 계산 결과를 표시합니다. '+txt(S.lastServerError):'';if(reconnecting){renderCalculationState();renderEvidenceSelectors();renderRegistration();}if(manual)message('변경된 데이터가 없습니다. 현재 결과를 유지합니다.');return;}S.lastServerError=result.last_error;S.capabilities=result.capabilities||{};S.server=Boolean(result.capabilities?.server);if(!S.server)throw new Error('작업실 API가 없는 주소입니다.');S.profiles=arr(result.profiles);S.history=arr(result.history);$('refresh-error').hidden=!result.last_error;$('refresh-error').textContent=result.last_error?'새 자료 갱신에 실패하여 이전 계산 결과를 표시합니다. '+txt(result.last_error):'';const nextSignature=stable([result.bundle?.generated_at,result.analysis?.options,result.history?.[result.history.length-1]?.id]);if(result.bundle&&result.analysis&&nextSignature!==S.stateSignature){const pending=S.dirty;S.stateSignature=nextSignature;if(!pending)S.options=normalizeOptions(result.analysis.options||{});setData(result.bundle,result.analysis);}else{renderProfiles();renderHistory();renderEvidenceSelectors();renderCalculationState();renderRegistration();}if(manual)message('최신 데이터와 계산 상태를 확인했습니다.');}catch(error){S.stateEtag=null;S.stateSignature=null;S.server=false;$('refresh-error').hidden=false;$('refresh-error').textContent='로컬 서버에 연결하지 못해 마지막으로 받은 결과를 표시합니다. '+error.message;if(manual)message(error.message,'error');renderCalculationState();renderEvidenceSelectors();renderRegistration();}}

